import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.Cz0TtJv6.js";const u=JSON.parse('{"title":"Easy setup (Railway)","description":"One-click Railway deploy for DLMM Bot. Paper first, then live from the dashboard.","frontmatter":{"title":"Easy setup (Railway)","description":"One-click Railway deploy for DLMM Bot. Paper first, then live from the dashboard."},"headers":[],"relativePath":"easy.md","filePath":"easy.md","lastUpdated":1786722483000}'),d={name:"easy.md"};function i(s,e,l,n,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="easy-setup-railway" tabindex="-1">Easy setup (Railway) <a class="header-anchor" href="#easy-setup-railway" aria-label="Permalink to &quot;Easy setup (Railway)&quot;">​</a></h1><p>One service. Attach a volume, open the URL, finish secrets in the dashboard.</p><p class="cta-row"><a class="doc-btn" href="https://railway.com?referralCode=SCj9lN" target="_blank" rel="noreferrer">Deploy on Railway</a><a class="doc-btn ghost" href="./api-keys">API keys</a><a class="doc-btn ghost" href="./agents">For AI agents</a></p><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><h3 id="_1-new-project-from-github" tabindex="-1">1. New project from GitHub <a class="header-anchor" href="#_1-new-project-from-github" aria-label="Permalink to &quot;1. New project from GitHub&quot;">​</a></h3><p>Railway → <strong>New Project → Deploy from GitHub</strong> → <code>CryptoGnome/dlmmbot</code> (or your fork). One service is enough — start/build come from <code>railway.toml</code>.</p><p>Boot defaults: paper mode, public <code>PORT</code>, volume-backed <code>config.toml</code> / <code>.env</code>, and a generated <code>DASH_TOKEN</code> in the logs if you didn’t set one.</p><h3 id="_2-volume-at-app-data" tabindex="-1">2. Volume at <code>/app/data</code> <a class="header-anchor" href="#_2-volume-at-app-data" aria-label="Permalink to &quot;2. Volume at `/app/data`&quot;">​</a></h3><p>Service → <strong>Volumes</strong> → Add → mount <code>/app/data</code>. Keeps SQLite, Settings, and the wallet across redeploys. Redeploy once after attaching.</p><h3 id="_3-public-domain" tabindex="-1">3. Public domain <a class="header-anchor" href="#_3-public-domain" aria-label="Permalink to &quot;3. Public domain&quot;">​</a></h3><p><strong>Settings → Networking → Generate domain.</strong> That’s the dashboard URL.</p><h2 id="open-the-dashboard" tabindex="-1">Open the dashboard <a class="header-anchor" href="#open-the-dashboard" aria-label="Permalink to &quot;Open the dashboard&quot;">​</a></h2><p>Open the domain. If <code>DASH_TOKEN</code> isn’t a Railway variable yet, copy <code>[railway] generated DASH_TOKEN=…</code> from <strong>Deploy logs</strong> and paste it at the login prompt. Then save it as a Railway variable so it doesn’t rotate.</p><h2 id="finish-in-settings" tabindex="-1">Finish in Settings <a class="header-anchor" href="#finish-in-settings" aria-label="Permalink to &quot;Finish in Settings&quot;">​</a></h2><p>First login opens a wizard: <strong>accept the Terms &amp; risk waiver</strong>, then RPC, Jupiter key, encrypted burner wallet, paper/live. Writes go to <code>/app/data</code> — the git checkout stays clean.</p><table tabindex="0"><thead><tr><th>Key</th><th>Required</th><th>Get it</th></tr></thead><tbody><tr><td><code>RPC_URL</code></td><td>Yes</td><td><a href="https://dashboard.helius.dev/signup" target="_blank" rel="noreferrer">Helius</a> mainnet URL</td></tr><tr><td><code>JUPITER_API_KEY</code></td><td>Before live</td><td><a href="https://developers.jup.ag/portal" target="_blank" rel="noreferrer">Jupiter Portal</a></td></tr><tr><td><code>GMGN_API_KEY</code></td><td>Optional</td><td><a href="https://gmgn.ai/ai" target="_blank" rel="noreferrer">gmgn.ai/ai</a></td></tr></tbody></table><p class="cta-row"><a class="doc-btn ghost" href="./api-keys">Full key signup</a><a class="doc-btn ghost" href="./profiles">Settings profiles</a></p><p>Stay in paper until you’re comfortable. Optional: set <code>WALLET_PASSPHRASE</code> on Railway to auto-unlock on boot.</p><h2 id="going-live" tabindex="-1">Going live <a class="header-anchor" href="#going-live" aria-label="Permalink to &quot;Going live&quot;">​</a></h2><p>Needs <strong>both</strong> <code>FARMER_MODE=live</code> (Railway variable or Settings) <strong>and</strong> <code>[exec] mode = &quot;live&quot;</code> in config. One switch alone stays paper. Restart/redeploy after both are set. One farmer process per wallet.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>Hobby (~$5) plus usage after trial credits — a volume needs a paid tier. Own hardware: <a href="./advanced">Advanced</a>.</p><p class="cta-row"><a class="doc-btn ghost" href="https://railway.com/pricing?referralCode=SCj9lN" target="_blank" rel="noreferrer">Railway pricing</a><a class="doc-btn ghost" href="./advanced">Advanced setup</a></p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Native module build fail</td><td>Node 20; check <code>better-sqlite3</code> logs</td></tr><tr><td>Dash unauthorized</td><td>Token from logs, or Railway <code>DASH_TOKEN</code></td></tr><tr><td>History / Settings wiped</td><td>Volume at <code>/app/data</code>, then redeploy</td></tr><tr><td>Healthcheck failing</td><td>Wait for first build; path is <code>/health</code></td></tr></tbody></table>',25)])])}const b=a(d,[["render",i]]);export{u as __pageData,b as default};
